// Desktop background renderer with click handling and transitions.
//
// This is a third-party plugin, so it deliberately does not use the reserved
// omarchy.* namespace. It is registered as acme.background.Background in the
// shell manifest, which is what the desktop-background service resolves to.
Item {
  id: root

  // Injected by the shell; kept here for the manifest and IPC signature only.
  property var shell: null

  // The shell keeps this loaded while the user is present, so it can keep the
  // transition running across screensaver invocations without restarting.
  property bool active: false

  // Bound into the scene graph via Loader.sourceComponent so the injected
  // Background component can be swapped out at runtime without tearing down
  // the whole scene. Keep this separate from the injected component so the
  // shell can swap it out without losing ownership of its own properties.
  property var injectedComponent: null
  property var injectedRoot: null

  // The injected component owns everything that needs to survive a reload:
  // the image source, the live preview texture, the fade target, the mask
  // sampler, and the bindings that drive them. Everything else — the scene
  // graph, the animation timeline, the IPC handlers — lives inside this
  // loader. Reloads tear down the loader and rebuild it fresh, so the next
  // render starts from a clean slate.
  Loader {
    anchors.fill: parent
    visible: true
    sourceComponent: root.injectedComponent
    onLoaded: {
      if ("root" in object)
        root.injectedRoot = object.root
      else
        root.injectedRoot = null
    }
    onStatusChanged: if (status === Loader.Error) console.warn("Background loader error:", sourceErrorString)
  }

  function inject(component) {
    injectedComponent = component
    injectedRoot = component ? component.root : null
  }

  function reload() {
    var next = ComponentUtils.loadQml(root, "Background.qml")
    inject(next)
    if (next.status === Component.Error)
      console.warn("Background reload failed:", next.errorString)
  }

