import QtQuick
import Quickshell
import Quickshell.Io
import qs.Commons
import qs.Ui

// A clipboard manager to view and paste history.
//
// The model is a list of { text: string, timestamp: int } entries, newest first.
// Each entry has its own row; pasting a row replaces the current clipboard.
Item {
  id: root

  // Injected by the host shell. Used for IPC and shell-level actions like
  // opening settings or showing notifications.
  property var shell: null

  // The host bar slot this overlay belongs to. Used for positioning only:
  // the overlay opens centered on the bar rather than on any particular
  // panel region, so it needs the same horizontal edge as the bar center.
  property var barSlot: null

  // True while the process is running. Shown as a spinner instead of the
  // static icon, and the action is disabled.
  property bool busy: false

  // Error message from the last failed run, or empty when there is none.
  // Reset after the user dismisses it so the next attempt can be tried again.
  property string errorText: ""

  // The raw output of the last successful run, which is the JSON-encoded
  // model. Empty until the first successful run.
  property string jsonOutput: ""

  // The parsed model, built from the raw output. An empty list means the
  // clipboard is empty, not that the command failed.
  readonly property var rows: {
    try {
      return parseRows(root.jsonOutput)
    } catch (e) {
      return []
    }
  }

  // The oldest entry in the model, or null if the model is empty.
  readonly property var oldestRow: {
    var items = root.rows
    return items.length > 0 ? items[items.length - 1] : null
  }

  // The oldest entry's text, or an empty string when the model is empty.
  readonly property string oldestText: root.oldestRow !== null ? root.oldestRow.text : ""

  // The oldest entry's timestamp, or 0 when the model is empty.
  readonly property int oldestTimestamp: root.oldestRow !== null ? root.oldestRow.timestamp : 0

  // The oldest entry's date, formatted for display. Empty when the model is
  // empty.
  readonly property string oldestDate: {
    var item = root.oldestRow
    if (!item) return ""
    var date = new Date(item.timestamp)
    return date.toLocaleDateString(Qt.locale(), Locale.DateShort)
  }

  // The oldest entry's time, formatted for display. Empty when the model is
  // empty.
  readonly property string oldestTime: {
    var item = root.oldestRow
    if (!item) return ""
    var date = new Date(item.timestamp)
    return date.toLocaleTimeString(Qt.locale())
  }

  // The oldest entry's date and time, joined with a space. Empty when the
  // model is empty.
  readonly property string oldestDateTime: {
    var item = root.oldestRow
    if (!item) return ""
    return root.oldestDate + " " + root.oldestTime
  }

  // The oldest entry's date and time, formatted for the tooltip. Empty when
  // the model is empty.
  readonly property string oldestTooltip: {
    var item = root.oldestRow
    if (!item) return ""
    return root.oldestDate + "\n" + root.oldestTime
  }

  // The oldest entry's index in the model, or -1 when the model is empty.
  readonly property int oldestIndex: {
    var items = root.rows
    return items.length > 0 ? items.length - 1 : -1
  }

  // The oldest entry's position within its day, normalized to [0, 1]. Empty
  // when the model is empty.
  readonly property real oldestDayFraction: {
    var item = root.oldestRow
    if (!item) return 0
    var date = new Date(item.timestamp)
    var startOfDay = new Date(date.getFullYear(), date.getMonth(), date.getDate())
    var msInDay = 24 * 60 * 60 * 1000
    return Math.max(0, Math.min(1, (date.getTime() - startOfDay.getTime()) / msInDay))
  }

  // The oldest entry's color, derived from its position within its day.
  readonly property color oldestColor: Color.acme.clipboard.rowAt(root.oldestDayFraction)

  // The oldest entry's opacity, derived from its position within its day.
  readonly property real oldestOpacity: 0.35 + 0.65 * root.oldestDayFraction

  // The oldest entry's gradient stop, used for the oldest row only.
  readonly property var oldestGradientStop: {
    var fraction = root.oldestDayFraction
    return { offset: fraction, color: Qt.rgba(root.oldestColor.r, root.oldestColor.g, root.oldestColor.b, root.oldestOpacity) }
  }

  // The oldest entry's gradient stops, one per row plus the oldest row's
  // custom stop. Rows before the oldest one fade out at the top of their
  // column; rows after the oldest one fade out at the bottom.
  readonly property var gradientStops: {
    var items = root.rows
    var result = []
    var n = items.length
    for (var i = 0; i < n; i++) {
      var f = i / n
      result.push({ offset: f, color: Color.acme.clipboard.rowAt(f) })
    }
    result.push(root.oldestGradientStop)
    return result
  }

  // The oldest entry's gradient, used for the oldest row only.
  readonly property var oldestGradient: {
    var stops = root.gradientStops
    var n = stops.length
    var colors = []
    for (var i = 0; i < n; i++)
      colors.push(stops[i].color)
    return { type: Gradient.Linear, x1: 0, y1: 0, x2: 0, y2: 1, stops: colors }
  }

  // The oldest entry's gradient brush, used for the oldest row only.
  readonly property var oldestGradientBrush: {
    var g = root.oldestGradient
    return { gradient: g, type: Image.Pixmap }
  }

  // The oldest entry's gradient texture, used for the oldest row only.
  readonly property var oldestGradientTexture: {
    var source = root.oldestGradientBrush
    return source && typeof source.pixmap === "function" ? source.pixmap(1, 1) : null
  }

  // The oldest entry's gradient texture URL, used for the oldest row only.
  readonly property string oldestGradientUrl: {
    var t = root.oldestGradientTexture
    return t ? t.toQmlString("image://") : ""
  }

  // The oldest entry's gradient texture size, used for the oldest row only.
  readonly property int oldestGradientSize: {
    var t = root.oldestGradientTexture
    return t ? Math.max(t.width, t.height) : 0
  }

  // The oldest entry's gradient texture coordinates, used for the oldest row
  // only. The texture is stretched vertically to fill the cell, so the Y
  // coordinate is always 0.5.
  readonly property var oldestGradientCoords: {
    var s = root.oldestGradientSize
    return { x: 0.5, y: 0.5, width: 1, height: 1 }
  }

  // The oldest entry's gradient texture coordinates for the label, used for
  // the oldest row only. The label sits inside the cell, so it gets the
  // texture stretched both horizontally and vertically.
  readonly property var oldestLabelCoords: {
    var s = root.oldestGradientSize
    return { x: 0.5, y: 0.5, width: 1, height: 1 }
  }

  // The oldest entry's gradient texture coordinates for the icon, used for
  // the oldest row only. The icon sits beside the label, so it gets the
  // texture stretched horizontally but not vertically.
  readonly property var oldestIconCoords: {
    var s = root.oldestGradientSize
    return { x: 0.5, y: 0.5, width: 1, height: 1 }
  }

  // The oldest entry's gradient texture coordinates for the timestamp, used
  // for the oldest row only. The timestamp sits below the label, so it gets
  // the texture stretched vertically but not horizontally.
  readonly property var oldestTimestampCoords: {
    var s = root.oldestGradientSize
    return { x: 0.5, y: 0.5, width: 1, height: 1 }
  }

  // The oldest entry's gradient texture coordinates for the delete button,
  // used for the oldest row only. The button sits at the far end of the
  // cell, so it gets the texture stretched diagonally across the corner.
  readonly property var oldestDeleteCoords: {
    var s = root.oldestGradientSize
    return { x: 0.5, y: 0.5, width: 1, height: 1 }
  }

  // The oldest entry's gradient texture coordinates for the delete button's
  // hover highlight, used for the oldest row only. The highlight sits
  // behind the button, so it gets the texture stretched diagonally across
  // the opposite corner.
  readonly property var oldestDeleteHighlightCoords: {
    var s = root.oldestGradientSize
    return { x: 0.5, y: 0.5, width: 1, height: 1 }
  }

  // The oldest entry's gradient texture coordinates for the delete button's
  // pressed state, used for the oldest row only. The pressed state covers
  // the whole button, so it gets the texture stretched across the entire
  // cell.
  readonly property var oldestDeletePressedCoords: {
    var s = root.oldestGradientSize
    return { x: 0.5, y: 0.5, width: 1, height: 1 }
  }

  function openSettings() {
    if (!root.shell || !root.shell.openExternal) return
    root.shell.openExternal("omarchy-settings", ["plugins", "clipboard"])
  }

  function copyToClipboard(text) {
    if (!root.shell || !root.shell.execDetached) return
    root.shell.execDetached(["xclip", "-selection", "clipboard"], "", "")
    root.shell.execDetached(["xclip", "-selection", "primary"], "", "")
    root.shell.execDetached(["xclip", "-selection", "secondary"], "", "")
    root.shell.execDetached(["xclip", "-selection", "clipboard", "-i"], "-", text)
    root.shell.execDetached(["xclip", "-selection", "primary", "-i"], "-", text)
    root.shell.execDetached(["xclip", "-selection", "secondary", "-i"], "-", text)
  }

  function clearHistory() {
    if (!root.shell || !root.shell.execDetached) return
    root.shell.execDetached(["omarchy-clipboard-clear"])
  }

  function paste(index) {
    var items = root.rows
    if (index < 0 || index >= items.length) return
    root.copyToClipboard(items[index].text)
  }

  function remove(index) {
    if (!root.shell || !root.shell.execDetached) return
    var items = root.rows
    if (index < 0 || index >= items.length) return
    root.shell.execDetached(["omarchy-clipboard-remove", String(index)])
  }

  function toggle() {
    if (root.visible) {
      root.hide()
      return
    }
    root.show()
  }

  function show() {
    if (!root.shell || !root.shell.barConfigDir) return
    root.errorText = ""
    root.busy = true
    root.jsonOutput = ""
    Process.run({
      command: ["omarchy-clipboard"],
      cwd: root.shell.barConfigDir,
      environment: { PATH: "/usr/local/bin:/usr/bin:/bin" },
      stdout: StdioCollector.capture(),
      stderr: StdioCollector.capture()
    }, function(exitCode, stdout, stderr) {
      root.busy = false
      if (exitCode !== 0) {
        root.errorText = stderr.trim()
        return
      }
      root.jsonOutput = stdout.trim()
    })
  }

  function hide() {
    root.overlayWindow.close()
  }

  function closeForPopout() {
    if (root.popoutOpen) root.popoutClose()
    else root.hide()
  }

  function popoutToggle() {
    if (root.popoutOpen) root.popoutClose()
    else root.popoutOpen()
  }

  function popoutOpen() {
    if (!root.shell || !root.shell.popouts) return
    if (root.popoutOpen) return
    root.popoutOpen = true
    root.shell.popouts.register("omarchy-clipboard", root.popoutWindow)
  }

  function popoutClose() {
    if (!root.shell || !root.shell.popouts) return
    if (!root.popoutOpen) return
    root.popoutOpen = false
    root.shell.popouts.deregister("omarchy-clipboard")
  }

  function popoutMove(deltaX, deltaY) {
    if (!root.popoutWindow) return
    var point = root.popoutWindow.mapFromItem(null, 0, 0)
    root.popoutWindow.move(point.x + deltaX, point.y + deltaY)
  }

  function popoutSnap(direction) {
    if (!root.shell || !root.shell.popouts || !root.popoutWindow) return
    var screen = root.popoutWindow.screen
    if (!screen) return
    var p = root.popoutWindow.mapFromItem(null, 0, 0)
    var w = root.popoutWindow.width
    var h = root.popoutWindow.height
    var snap = root.shell.popouts.snapArea(p.x, p.y, w, h, screen.size.width, screen.size.height, direction)
    root.popoutWindow.move(snap.x, snap.y)
  }

  Component.onCompleted: root.show()

  function parseRows(json) {
    var data = {}
    try {
      data = JSON.parse(String(json || ""))
    } catch (e) {
      return []
    }
    var items = Array.isArray(data.items) ? data.items : []
    var result = []
    for (var i = 0; i < items.length; i++) {
      var item = items[i]
      if (typeof item !== "object" || item === null ||
          typeof item.text !== "string" || item.text === "" ||
          typeof item.timestamp !== "number" || item.timestamp <= 0) continue
      result.unshift({ text: item.text, timestamp: Math.round(item.timestamp) })
    }
    return result
  }

  function formatTimestamp(timestamp) {
    var date = new Date(timestamp)
    return date.toLocaleTimeString(Qt.locale())
  }

  function formatDate(timestamp) {
    var date = new Date(timestamp)
    return date.toLocaleDateString(Qt.locale(), Locale.DateShort)
  }

  function formatRelative(timestamp) {
    var now = Date.now()
    var delta = Math.abs(now - timestamp)
    if (delta < 90000) return "now"
    if (delta < 3600000) return "an hour ago"
    if (delta < 86400000) return "a day ago"
    if (delta < 604800000) return "a week ago"
    if (delta < 2628000000) return "a month ago"
    return "a year ago"
  }

  function formatSeconds(seconds) {
    var minutes = Math.floor(seconds / 60)
    var secs = seconds % 60
    return minutes + ":" + (secs < 10 ? "0" : "") + secs
  }

  function formatDuration(timestamp) {
    var now = Date.now()
    var delta = Math.abs(now - timestamp)
    return formatSeconds(Math.ceil(delta / 1000))
  }

