    if (rows.length === 0) return "Clipboard"
    if (rows.length === 1) return "Clipboard · " + rows[0].text
    return "Clipboard · " + rows.length + " items"
  }

  function formatHint(rows) {
    if (rows.length === 0) return "No clipboard history yet."
    if (rows.length === 1) return "Paste with middle-click or right-click."
